import { PATH_TOKENS, PZN_FOLDER, TAG_PROMOTION_PREFIX } from '../constants.js';

export class Fragment {
    path = '';
    hasChanges = false;
    status = '';

    fields = [];

    selected = false;

    initialValue;

    /**
     * @param {*} AEM Fragment JSON object
     */
    constructor(fragment) {
        this.refreshFrom(fragment);
    }

    getField(fieldName) {
        return this.fields.find((field) => field.name === fieldName);
    }

    getFieldValues(fieldName) {
        return this.getField(fieldName)?.values || [];
    }

    getFieldValue(fieldName, index = 0) {
        return this.getFieldValues(fieldName)?.[index];
    }

    isValueEmpty(values) {
        return values.length === 0 || values.every((v) => v === '' || v === null || v === undefined);
    }

    get variant() {
        return this.getFieldValue('variant');
    }

    get fragmentName() {
        return this.path.split('/').pop();
    }

    get statusVariant() {
        return this.status?.toLowerCase();
    }

    getTagTitle(id) {
        const tags = this.tags.filter((tag) => tag.id.includes(id));
        return tags[0]?.title;
    }

    get locale() {
        const match = this.path.match(PATH_TOKENS);
        return match?.groups?.parsedLocale || '';
    }

    /**
     * Updates the fragment entirely while preserving the initial value & hasChange status if not specified
     * @param {object} fragmentData
     * @param {Boolean | undefined} hasChanges
     */
    replaceFrom(fragmentData, hasChanges) {
        const clonedData = structuredClone(fragmentData);
        Object.assign(this, clonedData);
        if (hasChanges === undefined) return;
        this.hasChanges = hasChanges;
    }

    refreshFrom(fragmentData) {
        this.replaceFrom(fragmentData, false);
        this.initialValue = structuredClone(fragmentData);
        this.newTags = undefined;
    }

    discardChanges() {
        if (!this.hasChanges) return;
        this.newTags = undefined;
        this.replaceFrom(this.initialValue, false);
    }

    updateFieldInternal(fieldName, value) {
        this[fieldName] = value ?? '';
        this.hasChanges = true;
    }

    getVariations() {
        return this.getFieldValues('variations') || [];
    }

    hasVariations() {
        const variations = this.getVariations();
        return variations.length > 0;
    }

    /**
     * Updates a field's values.
     * For variations: if values match parent exactly, resets to inherited state.
     * @param {string} fieldName - The field name to update
     * @param {Array} value - The new values
     * @param {Fragment|null} [parentFragment] - The parent fragment (for variations)
     * @returns {boolean|'reset'} - true if updated, false if no change, 'reset' if reset to parent
     */
    updateField(fieldName, value, parentFragment = null) {
        const encodedValues = value.map((v) => (typeof v === 'string' ? v.normalize('NFC') : v));
        const existingField = this.getField(fieldName);
        const isTags = fieldName === 'tags';
        const parentField = parentFragment?.getField(fieldName);

        // [''] is the explicit clear sentinel for multi-value fields
        const isSingleEmptyString = encodedValues.length === 1 && encodedValues[0] === '';

        // Determine if this is a multi-value field based on the .multiple property
        const isMultiple = parentField?.multiple === true || existingField?.multiple === true;

        // For variations: if values match parent exactly, reset to inherited state
        if (parentFragment) {
            const parentValues = parentField?.values || [];
            const valuesMatchParent =
                encodedValues.length === parentValues.length && encodedValues.every((v, i) => v === parentValues[i]);

            if (valuesMatchParent) {
                // Reset field if it exists, or just confirm it should stay inherited
                this.resetFieldToParent(fieldName);
                return 'reset';
            }
        }

        if (existingField) {
            const { values } = existingField;
            // Skip [] to [''] on single-value fields (RTE initialization sends [''] for empty fields).
            // For multiple:true fields, [''] is an explicit "clear" sentinel.
            if (values.length === 0 && isSingleEmptyString && !isMultiple) {
                return false;
            }
            // No change if values are identical
            if (values.length === encodedValues.length && values.every((v, i) => v === encodedValues[i])) {
                if (isTags) this.newTags = value;
                return false;
            }
            existingField.values = encodedValues;
            // Inherit multiple from parent field if not already set
            if (parentField?.multiple && !existingField.multiple) {
                existingField.multiple = true;
            }
        } else {
            // Only create new field if there's meaningful content
            // Exception: [''] is allowed as explicit clear sentinel for multi-value fields
            const hasContent = encodedValues.length && encodedValues.some((v) => v?.trim?.());
            if (!hasContent && !(isSingleEmptyString && isMultiple)) {
                if (isTags) this.newTags = value;
                return false;
            }
            const newField = { name: fieldName, type: 'text', values: encodedValues };
            // Inherit multiple from parent field
            if (parentField?.multiple) newField.multiple = true;
            this.fields.push(newField);
        }

        this.hasChanges = true;
        if (isTags) this.newTags = value;
        return true;
    }

    getEffectiveFieldValue(fieldName, parentFragment, isVariation, index = 0) {
        const ownValue = this.getFieldValue(fieldName, index);
        if (ownValue !== undefined && ownValue !== null && ownValue !== '') {
            return ownValue;
        }
        if (!parentFragment || !isVariation) {
            return ownValue;
        }
        return parentFragment.getFieldValue(fieldName, index);
    }

    getEffectiveFieldValues(fieldName, parentFragment, isVariation) {
        const ownField = this.getField(fieldName);
        const ownValues = ownField?.values || [];

        // [] (empty array) = inherit from parent if variation
        if (ownValues.length === 0) {
            if (!parentFragment || !isVariation) {
                return [];
            }
            const parentField = parentFragment.getField(fieldName);
            return parentField?.values || [];
        }

        // For [""] (single empty string):
        // - For multi-value fields (multiple: true): explicit clear sentinel → return empty array
        // - For single-value fields (multiple: false): AEM initializes empty fields this way → inherit from parent
        const isSingleEmptyString = ownValues.length === 1 && ownValues[0] === '';
        if (isSingleEmptyString) {
            const isMultipleField = ownField?.multiple === true;
            if (isMultipleField) {
                // Explicit clear for multi-value fields
                return [];
            }
            // Single-value field with [""] - inherit from parent if variation
            if (!parentFragment || !isVariation) {
                return [];
            }
            const parentField = parentFragment.getField(fieldName);
            return parentField?.values || [];
        }

        // Has actual values - return them
        return ownValues;
    }

    getFieldState(fieldName, parentFragment, isVariation) {
        if (!isVariation || !parentFragment) {
            return 'no-parent';
        }
        const ownField = this.getField(fieldName);
        const ownValues = ownField?.values || [];
        const parentValues = parentFragment.getFieldValues(fieldName) || [];

        // [] (empty array) = inherited
        if (ownValues.length === 0) {
            return 'inherited';
        }

        // For [""] (single empty string):
        // - For multi-value fields (multiple: true): this is explicit clear sentinel → overridden
        // - For single-value fields (multiple: false): AEM initializes empty fields this way → inherited
        const isSingleEmptyString = ownValues.length === 1 && ownValues[0] === '';
        if (isSingleEmptyString) {
            const isMultipleField = ownField?.multiple === true;
            if (!isMultipleField) {
                return 'inherited';
            }
            // For multiple fields, [""] is explicit clear - fall through to comparison
        }

        // Has actual values - compare with parent
        const normalizeForComparison = (v) => {
            if (v === null || v === undefined) return '';
            if (typeof v === 'string') {
                return v
                    .normalize('NFC')
                    .trim()
                    .replace(/\s+role="[^"]*"/g, '')
                    .replace(/\s+aria-level="[^"]*"/g, '');
            }
            return String(v);
        };

        const areEqual =
            ownValues.length === parentValues.length &&
            ownValues.every((v, i) => normalizeForComparison(v) === normalizeForComparison(parentValues[i]));

        return areEqual ? 'same-as-parent' : 'overridden';
    }

    isFieldOverridden(fieldName, parentFragment, isVariation) {
        return this.getFieldState(fieldName, parentFragment, isVariation) === 'overridden';
    }

    /**
     * Prepares a variation fragment for saving by resetting fields that match parent values.
     * This ensures we don't save inherited values as explicit overrides.
     * @param {Fragment} parentFragment - The parent fragment to compare against
     * @returns {Fragment} A clone of this fragment with inherited fields reset to []
     */
    prepareVariationForSave(parentFragment) {
        if (!parentFragment) return this;

        // Create a new Fragment instance from this fragment's data (constructor handles cloning)
        const prepared = new Fragment(this);

        // Fields that should never be reset (they're fragment-specific, not inherited)
        const excludeFields = ['variations', 'tags', 'originalId', 'locReady'];

        for (const field of prepared.fields) {
            if (excludeFields.includes(field.name)) continue;

            const fieldState = this.getFieldState(field.name, parentFragment, true);

            // If field is inherited or same-as-parent, reset to empty array
            // Only keep values that are truly overridden (different from parent)
            if (fieldState === 'inherited' || fieldState === 'same-as-parent') {
                field.values = [];
            }
        }

        return prepared;
    }

    resetFieldToParent(fieldName) {
        const fieldIndex = this.fields.findIndex((field) => field.name === fieldName);
        if (fieldIndex !== -1) {
            this.fields.splice(fieldIndex, 1);
            this.hasChanges = true;
            return true;
        }
        return false;
    }

    /**
     * Checks whether a path is a grouped (pzn) variation path.
     * @param {string} path
     * @returns {boolean}
     */
    static isGroupedVariationPath(path) {
        return path?.includes(`/${PZN_FOLDER}/`) ?? false;
    }

    /**
     * Categorizes all variation references in a single pass into locale, promo, and grouped buckets.
     * Each variation is classified into exactly one category (grouped > promo > locale).
     * @returns {{ locale: Object[], promo: Object[], grouped: Object[] }}
     */
    #categorizeVariations() {
        const variationPaths = this.getVariations();
        if (!variationPaths.length || !this.references?.length) {
            return { locale: [], promo: [], grouped: [] };
        }

        const referencesByPath = new Map(this.references.map((ref) => [ref.path, ref]));

        const currentMatch = this.path.match(PATH_TOKENS);
        const { surface, parsedLocale: currentLocale, fragmentPath } = currentMatch?.groups || {};

        const locale = [];
        const promo = [];
        const grouped = [];

        for (const path of variationPaths) {
            const reference = referencesByPath.get(path);
            if (!reference) continue;

            if (Fragment.isGroupedVariationPath(path)) {
                grouped.push(reference);
                continue;
            }

            const isPromo = reference.tags?.some((t) => t.id?.startsWith(TAG_PROMOTION_PREFIX));
            if (isPromo) {
                promo.push(reference);
                continue;
            }

            if (surface && currentLocale && fragmentPath) {
                const refMatch = path.match(PATH_TOKENS);
                if (refMatch?.groups) {
                    const r = refMatch.groups;
                    if (r.surface === surface && r.fragmentPath === fragmentPath && r.parsedLocale !== currentLocale) {
                        locale.push(reference);
                    }
                }
            }
        }

        return { locale, promo, grouped };
    }

    /**
     * Lists all locale variations of the fragment (regional variations).
     * @returns {Object[]}
     */
    listLocaleVariations() {
        return this.#categorizeVariations().locale;
    }

    /**
     * Lists all grouped (pzn) variations of the fragment.
     * @returns {Object[]}
     */
    listGroupedVariations() {
        return this.#categorizeVariations().grouped;
    }

    /**
     * Gets the count of grouped (pzn) variations.
     * @returns {number}
     */
    getGroupedVariationCount() {
        return this.#categorizeVariations().grouped.length;
    }

    /**
     * Gets the count of locale variations.
     * @returns {number}
     */
    getLocaleVariationCount() {
        return this.#categorizeVariations().locale.length;
    }

    /**
     * Gets the count of promo variations.
     * @returns {number}
     */
    getPromoVariationCount() {
        return this.#categorizeVariations().promo.length;
    }

    /**
     * Gets the total count of all variations (locale + promo + grouped).
     * @returns {number}
     */
    getTotalVariationCount() {
        const { locale, promo, grouped } = this.#categorizeVariations();
        return locale.length + promo.length + grouped.length;
    }
}

#!/usr/bin/env node

/**
 * Manual cleanup utility for MAS Studio fragments
 *
 * EXAMPLES:
 *
 * # Run with default values (2 days back, default automation test user)
 * node nala/utils/cleanup-cloned-cards.js
 *
 * # Preview what would be deleted without actually deleting (dry run)
 * node nala/utils/cleanup-cloned-cards.js --dry-run
 *
 * # Clean fragments for a different user
 * node nala/utils/cleanup-cloned-cards.js --user "<email>@adobe.com"
 *
 * # Clean fragments from last 7 days
 * node nala/utils/cleanup-cloned-cards.js --days 7
 *
 * # Clean fragments for specific user from last 5 days
 * node nala/utils/cleanup-cloned-cards.js --user "<email>@adobe.com" --days 5
 *
 * # Dry run with verbose output to see all details
 * node nala/utils/cleanup-cloned-cards.js --dry-run --verbose
 *
 * # Full example: specific user, 3 days back, dry run, verbose
 * node nala/utils/cleanup-cloned-cards.js --user "<email>@adobe.com" --days 3 --dry-run --verbose
 */

import { chromium, devices } from '@playwright/test';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const currentDir = dirname(fileURLToPath(import.meta.url));
const authFile = join(currentDir, '../.auth/user.json');
async function cleanupClonedCards(options = {}) {
    const {
        baseURL = process.env.PR_BRANCH_LIVE_URL || process.env.LOCAL_TEST_LIVE_URL || 'https://main--mas--adobecom.aem.live',
        daysBack = 2,
        dryRun = false,
        verbose = false,
        user = process.env.IMS_EMAIL || 'cod23684+masautomation@adobetest.com',
    } = options;

    console.log('🧹 MAS Studio Fragment Cleanup Utility');
    console.log('=========================================');
    console.log(`Target URL      : ${baseURL}`);
    console.log(`Days back       : ${daysBack}`);
    console.log(`Target user     : ${user}`);
    console.log(`Dry run         : ${dryRun ? 'Yes' : 'No'}`);
    console.log('');

    try {
        // Calculate the cutoff date
        const cutoffDate = new Date();
        cutoffDate.setDate(cutoffDate.getDate() - daysBack);
        const cutoffDateStr = cutoffDate.toISOString().split('T')[0]; // YYYY-MM-DD format

        if (verbose) {
            console.log(`Cleaning fragments created after: ${cutoffDateStr}`);
        }

        // Launch browser with same config as teardown
        let browser;
        try {
            browser = await chromium.launch();
            const context = await browser.newContext({
                ...devices['Desktop Chrome'],
                storageState: authFile,
                bypassCSP: true,
            });
            const page = await context.newPage();

            // Set HTTP headers for chromium
            await page.setExtraHTTPHeaders({
                'sec-ch-ua': '"Chromium";v="123", "Not:A-Brand";v="8"',
            });

            // Same API-based search as global teardown. Browser function receives all data via payload (no Node refs).
            const searchAndDeleteClonedCardsByAPI = async ({
                rootPath,
                pathFragment,
                cutoffDate,
                targetUser,
                processedIds,
                isDryRun,
                isVerbose,
            }) => {
                const repo = document.querySelector('mas-repository');
                if (!repo?.aem?.sites?.cf?.fragments?.search || typeof repo.deleteFragment !== 'function') {
                    return {
                        success: false,
                        error: 'mas-repository not ready for API search/delete',
                        deletedCount: 0,
                        failedCount: 0,
                        totalAttempted: 0,
                        fragmentsFound: 0,
                    };
                }
                const params = new URLSearchParams(pathFragment.replace(/^#/, ''));
                const path = params.get('path') || 'nala';
                const locale = params.get('locale') || 'en_US';
                const apiPath = `${rootPath}/${path}/${locale}`;
                const toDelete = [];
                try {
                    const cursor = repo.aem.sites.cf.fragments.search(
                        { path: apiPath, sort: [{ on: 'modifiedOrCreated', order: 'DESC' }] },
                        null,
                        null,
                    );
                    for await (const items of cursor) {
                        for (const item of items || []) {
                            if (!item?.id || processedIds.includes(item.id)) continue;
                            const createdBy = item.created?.by;
                            const createdAt = item.created?.at;
                            if (createdBy !== targetUser || !createdAt) continue;
                            const fragmentDate = String(createdAt).split('T')[0];
                            if (fragmentDate < cutoffDate) continue;
                            toDelete.push({
                                id: item.id,
                                title: item.title ?? '',
                                created: createdAt,
                                path: item.path,
                            });
                            if (isVerbose) {
                                console.log(`  Found: ${item.title ?? item.id} (${createdAt})`);
                            }
                        }
                    }
                } catch (error) {
                    return {
                        success: false,
                        error: (error?.message || String(error)).substring(0, 200),
                        deletedCount: 0,
                        failedCount: 0,
                        totalAttempted: 0,
                        fragmentsFound: 0,
                    };
                }
                if (toDelete.length === 0) {
                    return {
                        success: true,
                        deletedCount: 0,
                        deletedIds: [],
                        failedCount: 0,
                        totalAttempted: 0,
                        fragmentsFound: 0,
                        processedIds: [],
                    };
                }
                if (isDryRun) {
                    return {
                        success: true,
                        deletedCount: 0,
                        deletedIds: [],
                        failedCount: 0,
                        totalAttempted: toDelete.length,
                        fragmentsFound: toDelete.length,
                        processedIds: toDelete.map((f) => f.id),
                        dryRunFragments: toDelete.map((f) => ({ id: f.id, title: f.title, created: f.created })),
                    };
                }
                const deleteOptions = { startToast: false, endToast: false };
                const results = await Promise.allSettled(
                    toDelete.map((item) =>
                        repo
                            .deleteFragment({ id: item.id }, deleteOptions)
                            .then(() => ({ id: item.id, success: true }))
                            .catch((err) => ({
                                id: item.id,
                                success: false,
                                error: (err?.message || String(err)).substring(0, 200),
                                path: item.path,
                            })),
                    ),
                );
                const successful = results.filter((r) => r.status === 'fulfilled' && r.value?.success).map((r) => r.value.id);
                const failed = results
                    .filter((r) => r.status === 'rejected' || (r.status === 'fulfilled' && !r.value?.success))
                    .map((r) => ({
                        id: r.status === 'fulfilled' ? r.value?.id : 'unknown',
                        error:
                            r.status === 'fulfilled'
                                ? r.value?.error
                                : (r.reason?.message || String(r.reason)).substring(0, 200),
                        path: r.status === 'fulfilled' ? r.value?.path : undefined,
                    }));
                return {
                    success: failed.length === 0,
                    deletedCount: successful.length,
                    deletedIds: successful,
                    failedCount: failed.length,
                    failedFragments: failed,
                    totalAttempted: toDelete.length,
                    fragmentsFound: toDelete.length,
                    processedIds: toDelete.map((i) => i.id),
                };
            };

            // Define paths to check for fragments (different locales/views)
            const pathsToCheck = [
                '#page=content&path=nala',
                '#locale=fr_FR&page=content&path=nala',
                '#locale=en_CA&page=content&path=nala',
                '#locale=en_GB&page=content&path=nala',
                '#locale=en_AU&page=content&path=nala',
            ];

            let totalFragmentsFound = 0;
            let totalFragmentsDeleted = 0;
            const allFailedFragments = [];
            const processedFragmentIds = new Set();

            if (verbose) {
                console.log('🏠 Navigating to studio home...');
            }
            await page.goto(`${baseURL}/studio.html`);
            await page.waitForLoadState('domcontentloaded');
            await page.waitForTimeout(3000);

            for (const pathFragment of pathsToCheck) {
                console.log(`📍 Checking path: \x1b[33m${pathFragment}\x1b[0m`);

                await page.goto(`${baseURL}/studio.html${pathFragment}`);
                await page.waitForLoadState('domcontentloaded');

                await page.waitForFunction(
                    () => {
                        const repo = document.querySelector('mas-repository');
                        return repo?.aem?.sites?.cf?.fragments?.search && typeof repo.deleteFragment === 'function';
                    },
                    { timeout: 5000 },
                );

                await page.waitForTimeout(1000);

                const apiPayload = {
                    rootPath: '/content/dam/mas',
                    pathFragment,
                    cutoffDate: cutoffDateStr,
                    targetUser: user,
                    processedIds: Array.from(processedFragmentIds),
                    isDryRun: dryRun,
                    isVerbose: verbose,
                };
                const cleanupResult = await page.evaluate(searchAndDeleteClonedCardsByAPI, apiPayload);

                // Log results for this specific path
                if (cleanupResult.fragmentsFound > 0) {
                    if (dryRun) {
                        console.log(`  \x1b[33m⚠\x1b[0m  Would delete ${cleanupResult.fragmentsFound} fragments (dry run)`);
                        if (verbose && cleanupResult.dryRunFragments) {
                            cleanupResult.dryRunFragments.forEach((frag) => {
                                console.log(`      - ${frag.title} (${frag.created})`);
                            });
                        }
                    } else {
                        const failedCount = cleanupResult.failedCount || 0;
                        if (failedCount > 0) {
                            console.log(
                                `  \x1b[33m⚠\x1b[0m Found ${cleanupResult.fragmentsFound} fragments, deleted ${cleanupResult.deletedCount}, failed ${failedCount}`,
                            );
                            if (cleanupResult.failedFragments) {
                                cleanupResult.failedFragments.forEach((frag) => {
                                    const pathInfo = frag.path ? ` (path: ${frag.path})` : '';
                                    console.log(
                                        `      \x1b[31m✘\x1b[0m Failed: ${frag.id}${pathInfo} - ${frag.error || 'Unknown error'}`,
                                    );
                                });
                            }
                        } else {
                            console.log(
                                `  \x1b[32m✓\x1b[0m Found ${cleanupResult.fragmentsFound} fragments, deleted ${cleanupResult.deletedCount}`,
                            );
                        }
                    }
                } else {
                    console.log(`  ➖ No fragments found in this path`);
                }

                // Accumulate results from this path
                totalFragmentsFound += cleanupResult.fragmentsFound || 0;
                totalFragmentsDeleted += cleanupResult.deletedCount || 0;

                if (cleanupResult.failedFragments) {
                    allFailedFragments.push(...cleanupResult.failedFragments);
                }

                // Track processed fragment IDs to avoid duplicates in next path
                if (cleanupResult.processedIds) {
                    cleanupResult.processedIds.forEach((id) => processedFragmentIds.add(id));
                }
            }

            // Print summary
            console.log(`\n${'='.repeat(42)}`);
            console.log('Summary:');
            console.log(`  Total fragments found      : ${totalFragmentsFound}`);
            if (dryRun) {
                console.log(`  \x1b[33mWould delete (dry run)     : ${totalFragmentsFound}\x1b[0m`);
            } else {
                console.log(`  \x1b[32m✓\x1b[0m Successfully deleted     : ${totalFragmentsDeleted}`);
                if (allFailedFragments.length > 0) {
                    console.log(`  \x1b[31m✘\x1b[0m Failed to delete         : ${allFailedFragments.length}`);
                    console.log('\nFailed fragments:');
                    allFailedFragments.forEach((fragment) => {
                        const pathInfo = fragment.path ? ` (path: ${fragment.path})` : '';
                        console.log(`  \x1b[31m✘\x1b[0m ${fragment.id}${pathInfo}: ${fragment.error || 'Unknown error'}`);
                    });
                }
            }
            console.log('='.repeat(42));

            return {
                success: allFailedFragments.length === 0,
                deletedCount: totalFragmentsDeleted,
                failedCount: allFailedFragments.length,
                totalAttempted: totalFragmentsFound,
            };
        } catch (error) {
            throw error;
        } finally {
            // Always close browser if it was opened
            if (browser) {
                await browser.close();
            }
        }
    } catch (error) {
        console.error('\x1b[31m✘\x1b[0m Cleanup failed:', error.message);
        if (verbose) {
            console.error(error.stack);
        }
        process.exit(1);
    }
}

// CLI interface
if (process.argv[1] === fileURLToPath(import.meta.url)) {
    const args = process.argv.slice(2);
    const options = {};

    for (let i = 0; i < args.length; i++) {
        const arg = args[i];

        if (arg === '--help' || arg === '-h') {
            console.log(`
MAS Studio Fragment Cleanup Utility

Usage:
  node cleanup-cloned-cards.js [options]

Options:
  --days <number>   Number of days back to clean (default: 2)
  --url <url>       Base URL to clean (default: from env or main--mas--adobecom.aem.live)
  --user <email>    Target user email (default: IMS_EMAIL env var or cod23684+masautomation@adobetest.com)
  --dry-run         Preview what would be deleted without actually deleting
  --verbose, -v     Show detailed output
  --help, -h        Show this help message

Examples:
  # Dry run to preview what would be deleted
  node cleanup-cloned-cards.js --dry-run

  # Clean fragments from last 7 days with verbose output
  node cleanup-cloned-cards.js --days 7 --verbose

  # Clean fragments for a specific user
  node cleanup-cloned-cards.js --user "myemail@example.com"

  # Clean from a specific URL
  node cleanup-cloned-cards.js --url https://main--mas--adobecom.aem.live

  # Combine options
  node cleanup-cloned-cards.js --days 3 --user "test@example.com" --dry-run --verbose
            `);
            process.exit(0);
        } else if (arg === '--days') {
            options.daysBack = parseInt(args[++i], 10);
        } else if (arg === '--url') {
            options.baseURL = args[++i];
        } else if (arg === '--user') {
            options.user = args[++i];
        } else if (arg === '--dry-run') {
            options.dryRun = true;
        } else if (arg === '--verbose' || arg === '-v') {
            options.verbose = true;
        }
    }

    cleanupClonedCards(options);
}

